/**
 * PWA 壳 —— manifest、service worker、应用图标。
 *
 * 设计取舍：
 *   · 图标是代码生成的 16×16 像素小人（与办公区 8-bit 工位同一审美），
 *     以 base64 内嵌在本文件里 —— 控制台保持"零构建、无静态资源目录"，
 *     Hub 不需要读盘就能交出全部 PWA 资源。
 *   · service worker 只做静态壳缓存（/ui.js、图标、manifest），且**一律网络优先**，
 *     缓存只当离线兜底（cache-first 曾把 /ui.js 冻在客户端，见下方长注释）；
 *     **绝不**拦截 /ws 与 /api：控制面 WS 与 RPC 必须永远直连 Hub，
 *     离线缓存一个"看起来能用的控制台"只会掩盖断线。
 *   · iOS 没有 beforeinstallprompt，安装路径是 Safari「分享 → 添加到主屏幕」；
 *     apple-touch-icon 只认 PNG（不支持 SVG），所以 180/192/512 三张都是 PNG。
 */

import { contentHash } from '../protocol/build.ts'

export interface WebManifestOptions {
  hubName: string
}

/** 与 HTML <head> 里的主题色保持一致（:root 浅色 / dark 深色面板的取色）。 */
const MANIFEST_BACKGROUND = '#ffffff'
const MANIFEST_THEME = '#161a22'

export function renderWebManifest(options: WebManifestOptions): string {
  return JSON.stringify({
    name: `DSEmployee 控制台 · ${options.hubName}`,
    short_name: options.hubName,
    start_url: '/',
    scope: '/',
    display: 'standalone',
    background_color: MANIFEST_BACKGROUND,
    theme_color: MANIFEST_THEME,
    icons: [
      { src: '/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
    ],
  })
}

/**
 * 内容指纹 —— 用来给「控制台脚本」这个资源做版本号。
 *
 * 哈希实现在 `src/protocol/build.ts`：同一个函数也用于**节点代码指纹**，
 * 全仓只保留一份实现，免得两个地方各算各的、结果还对不上。
 */
export function assetVersion(source: string): string {
  return contentHash(source)
}

export interface PwaServiceWorkerOptions {
  /** 控制台脚本的内容指纹（`assetVersion(CONTROL_UI_SCRIPT)`）。 */
  version: string
  /** 控制台脚本地址，含版本查询串（如 `/ui.js?v=abc-123`）。 */
  scriptUrl: string
}

/**
 * service worker 源码（/sw.js，根作用域）。
 *
 * 策略：
 *   · 全部同源 GET 一律 **network-first**，网络失败才回落缓存；
 *   · 页面导航同理，最后回落到缓存的 '/'；
 *   · /ws、/api 一律放行不干预。
 *
 * **为什么不再用 cache-first**（这里踩过一次真实的坑，别再改回去）：
 * 上一版对非导航请求用 cache-first，并把 `/ui.js` 放进 precache 列表。service worker
 * 只在 **service worker 脚本自身字节变化**时才更新，"缓存名写死 v2 + SW 脚本内容不再变"两条合起来
 * ⇒ SW 永不换代 ⇒ `/ui.js` 永远命中旧缓存、网络请求根本不发生。结果是**页面 HTML
 * （network-first）每次都是新的，而 JS 永远停在装上那天**：CSS 改了、JS 没改，
 * 客户端跑在"新样式 + 旧代码"的错配态里。手机上表现为办公区卡片与电脑完全不同
 * （旧代码根本不建 `.desk-top` 这层网格，新样式整块空转），而且刷新、重启、重开 PWA
 * 都不会自愈。
 *
 * network-first 之后，"忘记升版本"这个坑从结构上消失了：缓存只承担离线兜底，
 * 在线状态下的资源永远来自网络（服务端已给 /ui.js 与 /sw.js 发 no-cache，走 304 校验）。
 * precache 仍保留，作用是**首次访问后立刻具备离线能力**。
 *
 * 本字符串不参与 tsc 检查 —— 改动后用
 *   node --input-type=module -e "import('./src/web/pwa.ts').then(m=>{const fs=require('node:fs');fs.writeFileSync('sw-check.js', m.renderPwaServiceWorker({version:'t',scriptUrl:'/ui.js?v=t'}))})"
 *   node --check sw-check.js
 * 验证语法（内容是 ES5 风格：不用模板字符串/箭头函数以外的现代特性也可以，
 * 但保持和 CONTROL_UI_SCRIPT 同款 ES5 写法，老 WebView 也能跑）。
 */
export function renderPwaServiceWorker(options: PwaServiceWorkerOptions): string {
  const cacheName = `dse-pwa-${options.version}`
  return String.raw`
var CACHE = '${cacheName}'
var SCRIPT = '${options.scriptUrl}'
var PRECACHE = [SCRIPT, '/manifest.webmanifest', '/icon-180.png', '/icon-192.png', '/icon-512.png']

self.addEventListener('install', function (event) {
  event.waitUntil(
    caches.open(CACHE).then(function (cache) { return cache.addAll(PRECACHE) }).then(function () {
      return self.skipWaiting()
    }),
  )
})

self.addEventListener('activate', function (event) {
  event.waitUntil(
    caches.keys().then(function (keys) {
      return Promise.all(keys.map(function (key) {
        if (key !== CACHE) return caches.delete(key)
        return undefined
      }))
    }).then(function () { return self.clients.claim() }),
  )
})

/* 离线兜底：网络失败且缓存里也没有时，回一个明确的 503 而不是让浏览器抛网络错误 ——
   "服务不可达"和"资源不存在"是两回事，控制台会把它显示成断线提示。 */
function offlineResponse() {
  return new Response('offline', {
    status: 503,
    statusText: 'offline',
    headers: { 'content-type': 'text/plain; charset=utf-8' },
  })
}

/* 网络优先：拿到响应就顺手更新缓存；失败回落缓存；再失败给离线响应。 */
function networkFirst(request, fallbackKey) {
  return fetch(request).then(function (response) {
    if (response !== undefined && response.ok) {
      var copy = response.clone()
      caches.open(CACHE).then(function (cache) { cache.put(fallbackKey, copy) })
    }
    return response
  }).catch(function () {
    return caches.match(fallbackKey).then(function (hit) {
      if (hit) return hit
      return offlineResponse()
    })
  })
}

/* ── Web Push：手机上收到通知 ──
 *
 * 这一段是"手机通知"能成立的最后一环：没有它，推送服务把消息送达了浏览器，
 * 浏览器却不知道该显示什么（而且 iOS 会因此把订阅判为无效）。
 *
 * 两条约定：
 *   · 载荷由 Hub 按 RFC 8291 加密，这里只是解出来的 JSON（title/body/tag）；
 *   · **必须** showNotification：iOS 上"收到推送但不弹通知"会被系统当成滥用，
 *     几次之后订阅就废了（表现是"某天开始再也收不到"）。
 */
self.addEventListener('push', function (event) {
  var data = { title: 'DSEmployee', body: '' }
  try {
    if (event.data) data = Object.assign(data, event.data.json())
  } catch (error) {
    /* 解不出来也要弹：宁可显示标题，也别静默丢一条 */
  }
  event.waitUntil(
    self.registration.showNotification(data.title || 'DSEmployee', {
      body: data.body || '',
      tag: data.tag || 'dse',
      data: { url: data.url || '/' },
    }),
  )
})

/* 点通知：已经在控制台就把那个窗口拉到前面，否则新开一个 */
self.addEventListener('notificationclick', function (event) {
  event.notification.close()
  var target = (event.notification.data && event.notification.data.url) || '/'
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function (list) {
      for (var i = 0; i < list.length; i += 1) {
        if ('focus' in list[i]) return list[i].focus()
      }
      if (self.clients.openWindow) return self.clients.openWindow(target)
      return undefined
    }),
  )
})

self.addEventListener('fetch', function (event) {
  var request = event.request
  if (request.method !== 'GET') return
  var url = new URL(request.url)
  if (url.origin !== location.origin) return
  /* 控制面与 RPC 永不进缓存：它们必须在场且实时 */
  if (url.pathname === '/ws' || url.pathname.indexOf('/api') === 0) return

  /* 导航统一用 '/' 做缓存键：不管用户是从 / 还是 /index.html 进来，
     离线时都回落到同一份壳。其余资源按自身 URL 缓存。 */
  if (request.mode === 'navigate') {
    event.respondWith(networkFirst(request, '/'))
    return
  }

  event.respondWith(networkFirst(request, request))
})
`
}

/* ── 应用图标（16×16 像素小人，最近邻放大；RGBA PNG，不透明背景） ── */

const ICON_180 =
  ''

const ICON_192 =
  ''

const ICON_512 =
  ''

/** 应用图标的二进制内容（base64 → Buffer），键即路由路径。 */
export const PWA_ICONS: Record<string, string> = {
  '/icon-180.png': ICON_180,
  '/icon-192.png': ICON_192,
  '/icon-512.png': ICON_512,
}
